    "summary": "The patient experiences severe anticipatory and in-the-moment anxiety about crossing large bridges, a fear that becomes especially intense when the route cannot be avoided, such as driving to pick up elderly parents from the airport. The distress begins a week in advance and builds steadily. During the crossing, the patient vividly imagines the car flying off the bridge, drives slowly in the middle lane, keeps the radio on and windows down, and even keeps a hard metal tool by the door to break the glass in an emergency. Anxiety peaks near toll points and 'last exit' signs and worsens with trucks, bad weather, or darkness. The patient knows the risk is objectively low but still scans railing spacing as if calculating escape routes. Overall, the patient seems caught between a strong sense of duty toward family and an entrenched bridge phobia present for many years.",
    "current_context": "A school-age boy was brought for evaluation because a longstanding fear of crossing large bridges has become difficult to manage when travel routes cannot be avoided, particularly during required trips involving transportation for elderly family members.\nPrecipitating factors:\n- Recent unavoidable trips involving bridge crossings to pick up elderly parents from the airport have increased the frequency and urgency of the problem.\n- Ongoing family caregiving demands have made route avoidance less workable, bringing the longstanding fear into sharper functional focus.",
