    "summary": "The patient is a senior college student who appears highly functional on the surface, juggling a double major, athletics, sorority responsibilities, and strong grades, yet has recently been unsettled by a series of panic attacks that feel frightening and unexplained. Over the past month, five or six attacks have occurred, many at night and at least one during a break with no academic pressure, which shook the assumption that the episodes were tied to ordinary stress. During the attacks the patient feels scared, short of breath, and helpless. Underneath the confusion are hints of cumulative pressure: approaching graduation, leadership expectations on a sports team, and the edge of a major life transition. The patient has not told friends about the attacks and feels wary of medication. Overall, the patient seems frightened less by a specific trigger than by the feeling that alarming symptoms are appearing from nowhere just as adult expectations are intensifying.",
    "current_context": "A senior African American male college student with strong academic and extracurricular functioning was referred after experiencing a recent cluster of recurrent panic attacks, including nighttime episodes and one during a school break, in the context of heavy academic, athletic, and leadership demands as graduation approaches.\nPrecipitating factors:\n- Over the past semester, pressure has intensified around graduation planning, a looming transition out of college, and decisions about next steps after school.\n- Recent leadership demands in athletics and other campus responsibilities have increased performance pressure and reduced recovery time.\n- A cluster of five to six panic attacks over the past month, including nighttime episodes and one during a break from academic demands, prompted referral for evaluation.",
