    "summary": "The patient is a teenager living with a single parent who works multiple jobs to keep the household afloat, and has gradually come to believe that simply existing and having needs makes the parent's already difficult life harder. The patient describes feeling guilty about everything from eating food in the house to asking for school supplies, and tries to take up as little space as possible by staying in their room, skipping meals, and never mentioning when something is needed. At school the patient functions adequately but feels detached and heavy, as though going through the motions without any sense that efforts matter. Friendships have been dropped because socializing requires energy and sometimes money the patient does not want to ask for, and the isolation has deepened a persistent sadness. What makes the situation especially painful is that the patient loves the parent and can see how hard they work, which only intensifies the belief that the patient should need less and cause less trouble. These feelings are not discussed at home for fear of adding another burden.",
    "current_context": "Referred by a school counselor after several months of noticeable social withdrawal, reduced lunch intake, and a decline in engagement despite continued school attendance and adequate assignment completion. Concern increased when teachers observed that she appeared persistently tired, detached from peers, and difficult to draw into conversation.\nPrecipitating factors:\n- Over the past school term, the parent’s work demands appear to have increased, with less time at home and greater visible financial stress.\n- As peer activities and school expenses increased during the school year, she further reduced social participation and stopped raising routine needs at home.\n- Teachers and the school counselor became more concerned after observing persistent withdrawal, low energy, and reduced eating over several months.",
    "relevant_history": "Psychological history:\n- Age 12: after her parent took on additional shifts, she began spending more afternoons and evenings alone at home and started handling her own meals and school preparation without asking for help.\n- Age 13: she stopped mentioning routine school needs such as field trip fees, supplies, and replacement clothing after seeing her parent become visibly stressed while reviewing bills at the kitchen table.\n- Over the past 1-2 years, she has developed a pattern of withdrawing to her room when upset and keeping problems to herself rather than seeking comfort or assistance.\nSocial history:\n- Since early adolescence, she has lived with a single parent who works multiple jobs, leaving the household organized around scarcity, exhaustion, and trying not to add demands.\n- In her school and home life, limited money for food, clothes, activities, and supplies has repeatedly signaled that needs must be deferred, and she has had fewer chances for low-cost social participation with peers.",
