    "short_description": "The patient's anxiety is especially triggered by emotionally explosive people, particularly older authority figures, and the body still reacts as if…",
    "summary": "The patient's anxiety is especially triggered by emotionally explosive people, particularly older authority figures, and the body still reacts as if danger is present even when no one is actually angry. The problem seems rooted in a previous workplace around age 20 where anger was constantly in the air and the patient, unable to express frustration directly, absorbed everyone else's complaints until quitting. Leaving helped temporarily, and the patient now freelances from home with more safety and control. But the fear has spread: even around kind people, the patient suddenly thinks 'What if I make this person angry?' and then becomes visibly awkward, jumbles words, and struggles harder the more they try to act normal. A dream about a generous work contact yelling revealed that simply avoiding explosive people is not enough, because the fear now extends into anticipation and self-consciousness in safe relationships. The idea of returning to in-person office life feels almost unbearably threatening.",
    "current_context": "An adult male working freelance from home presented for assessment due to worsening anxiety in professional and interpersonal situations, particularly around older authority figures and people perceived as emotionally explosive. Although symptoms initially improved after leaving a highly conflictual workplace in early adulthood, he now reports anxiety generalizing to otherwise safe interactions and increasing difficulty imagining a return to in-person office work.\nPrecipitating factors:\n- A recent dream in which a previously supportive work contact was yelling appears to have highlighted that the fear has spread beyond overtly explosive people to safe professional relationships.\n- Growing pressure to consider more in-person professional contact has made the possibility of returning to office environments feel increasingly unmanageable.\n- Recent episodes of becoming visibly tense and verbally disorganized even with kind people have made the problem harder to contain through simple avoidance.",
    "relevant_history": "Psychological history:\n- Age 20: in an early workplace, he spent extended periods around chronically angry, emotionally explosive coworkers and senior staff, with conflict felt as a constant background condition.\n- Age 20: when upset in that workplace, he did not express frustration directly and instead listened to others' complaints, absorbing tension until he eventually quit.\n- After leaving that job, immediate relief appears to have taught him that distance from conflict was the main way to regain safety, strengthening an avoidant coping pattern.\nSocial history:\n- As a young adult in an office environment, he had repeated exposure to older authority figures whose anger had practical consequences for workload, evaluation, and daily atmosphere.\n- Freelance home-based work later offered safety and autonomy but also reduced routine contact with ordinary in-person workplace interactions that might have challenged threat expectations.",
    "coping_strategies": [
      "Works remotely and structures his schedule to minimize in-person meetings, office settings, and direct exposure to potentially critical or emotionally intense people.",
      "Carefully scans others' tone, facial expression, and level of irritation; becomes visibly tense, rehearses what to say, and speaks more cautiously when he anticipates scrutiny.",
      "Keeps interactions polite, brief, and task-focused; limits disagreement and personal disclosure; leaves or declines situations that feel likely to become confrontational or overwhelming."
    ],
