    "summary": "The patient becomes intensely nervous whenever speaking or performing in front of others, and this fear seems organized around a humiliating memory from elementary school when the patient's voice cracked during a presentation, everyone laughed, and it felt like the worst possible public failure. Since then, standing in front of people has meant anticipating blanking out, being laughed at again, and proving to themselves that they are the one person who cannot do what everyone else manages. The anxiety is specific rather than generalized: the patient is fine in ordinary group situations but wants to run away once attention is focused on them. The pattern has led to years of avoidance, including going to the nurse's office instead of presenting. The immediate trigger for seeking help is an upcoming singing test, which feels especially threatening. Yet the patient is not completely resigned: another part wants a different outcome this time and keeps practicing even while feeling scared.",
    "current_context": "A female student was referred for help because an upcoming singing test at school has led to escalating distress, repeated avoidance behaviors, and difficulty participating in required class performance tasks.\nPrecipitating factors:\n- A scheduled singing test has created a near-term, unavoidable performance demand in which she will be individually evaluated.\n- Recent awareness that she cannot continue using her usual avoidance strategies for every assessed performance task has increased help-seeking now.",
