    "summary": "The patient is a bank employee who for about six months has been living in fear of sudden episodes of racing heart, chest pain, breathlessness, and the conviction of dying. The first attack came on a hot day during a period of rising work stress after a new manager arrived and a new computer system increased pressure. The patient was so frightened that they sat down and called a family member for help. Since then the patient has become hyperaware of every heartbeat change, spiraling quickly into thoughts that the heart might stop, a fear intensified by a parent having died of a heart attack. Even though an ECG was normal, the patient still struggles to believe the heart is truly fine and only recently has begun to wonder whether panic could explain it. The patient now avoids going into town alone, depends on a partner for transport, has stopped exercising for fear of cardiac strain, and backed out of social plans imagining becoming ill and embarrassing everyone. The problem is shrinking daily life and straining an otherwise supportive relationship.",
    "current_context": "A male bank employee was referred after around six months of recurrent acute physical episodes and increasing avoidance began to interfere with independent travel, exercise, social activity, and his relationship, despite prior medical reassurance.\nPrecipitating factors:\n- Over the past six months, a new manager introduced closer performance scrutiny and a new computer system increased workload pressure at the bank.\n- The first acute episode occurred on a hot workday during escalating job stress, leading to a sudden collapse into help-seeking at work.\n- Despite a normal ECG, ongoing physical sensations and repeated disruption to travel, exercise, and social plans led to referral as functioning narrowed.",
    "relevant_history": "Psychological history:\n- Age 8: after his father died suddenly from a heart attack, adults in the family spoke often about symptoms being missed and the need to take chest pain seriously.\n- Age 10 to 12: he became the child who watched for signs that his remaining parent was overtired or unwell and was praised for being sensible rather than making a fuss.\n- Through secondary school, he coped with stress by keeping worries to himself and pushing on until physical discomfort forced him to stop.\nSocial history:\n- He grew up in a working family where men were expected to get on with things, not miss shifts, and treat bodily strain as part of earning a living.\n- In his local community, health concerns were often discussed in practical, worst-case terms, and sudden cardiac death in middle-aged men was treated as something that could strike without warning.",
