    "summary": "The patient, who lives alone, has been deeply grief-stricken since the death of a beloved pet three months ago and has found it impossible to resume normal life. For fourteen years, this animal was the center of daily routine: morning walks structured the schedule, evening care gave a sense of purpose, and the pet's presence in the apartment was the main source of comfort after work. Since the death, the patient describes waking up to an empty apartment that feels unbearable, crying unpredictably throughout the day, and losing interest in meals, exercise, and the few social connections that existed. The patient is embarrassed by the intensity of the grief because others are expected to see mourning a pet this deeply as excessive, and this expectation has prevented telling most people how bad things are. The pet's belongings remain in their usual places because putting them away feels like admitting the loss is final. Friends have suggested adopting another animal, which the patient experiences as dismissive. Overall, the patient appears isolated, ashamed of the grief, and unable to rebuild daily structure.",
    "current_context": "A 74-year-old Caucasian woman who lives alone and works part-time in a service role was referred for assessment after three months of marked decline in daily functioning following the death of her long-term pet. Since the loss, her routine, self-care, social contact, and work functioning have deteriorated, raising concern for a depressive episode in addition to bereavement; medical, substance-related, and bipolar contributors are to be assessed.\nPrecipitating factors:\n- Death of her pet three months ago after fourteen years of providing daily companionship and routine.\n- Progressive loss of daily structure since the pet's death, including stopping morning walks, irregular meals, and reduced contact with friends.\n- Recent disclosure during a routine primary care visit after visible tearfulness and report of declining ability to manage usual self-care and part-time service work responsibilities.",
    "relevant_history": "Psychological history:\n- Age 11: after her parents' divorce, she spent many afternoons alone until her mother returned from work, learning to keep distress private and rely on routines to get through the day.\n- Age 39: following the death of her husband, she returned to work within two weeks and managed grief largely by staying busy and avoiding discussion of the loss.\n- Around age 67: after reducing to part-time service work, most evenings were spent at home with the pet, and the animal became her main source of comfort and daily purpose.\nSocial history:\n- For years in her social circle and workplace, she heard the message that 'you just keep going' and do not burden others with private upset, especially after losses that others may see as minor.\n- She lives alone in an apartment with limited nearby family contact, and several friendships narrowed after retirement-age transitions and schedule changes, leaving the pet as her most consistent companion.",
